import fitz, docx, os

def dump_pdf(path):
    print(f'=== {os.path.basename(path)} ===')
    doc = fitz.open(path)
    for i, page in enumerate(doc):
        print(f'--- Page {i+1} ---')
        print(page.get_text())

def dump_docx(path):
    print(f'=== {os.path.basename(path)} ===')
    doc = docx.Document(path)
    for p in doc.paragraphs:
        if p.text.strip():
            print(p.text)
    for table in doc.tables:
        for row in table.rows:
            print([c.text.strip() for c in row.cells])

dump_docx('final_batch4__structural_task6_seismic_diaphragm_shear__blind/project/00_admin/OBD-CDDC-B_Owners_Basis_of_Design_extract.docx')
