import ezdxf

def inspect_layer(dxf_path, layer_name):
    doc = ezdxf.readfile(dxf_path)
    msp = doc.modelspace()
    print(f'=== {dxf_path} Layer: {layer_name} ===')
    for e in msp:
        if e.dxf.layer == layer_name:
            if e.dxftype() == 'LINE':
                print(f'LINE ({e.dxf.start.x:.1f}, {e.dxf.start.y:.1f}) -> ({e.dxf.end.x:.1f}, {e.dxf.end.y:.1f})')
            elif e.dxftype() == 'LWPOLYLINE':
                pts = e.get_points('xy')
                print('LWPOLYLINE', [(round(p[0], 1), round(p[1], 1)) for p in pts])
            elif e.dxftype() in ('TEXT', 'MTEXT'):
                print(f'TEXT \"{e.dxf.text}\" at ({e.dxf.insert.x:.1f}, {e.dxf.insert.y:.1f})')

