import json

with open('final_batch4__structural_task6_seismic_diaphragm_shear__blind/templates/design_record.json') as f:
    tmpl = json.load(f)

with open('final_batch4__structural_task6_seismic_diaphragm_shear__blind/output/design_record.json') as f:
    actual = json.load(f)

def compare_keys(t, a, path=''):
    if isinstance(t, dict):
        if not isinstance(a, dict):
            print(f'Type mismatch at {path}: expected dict, got {type(a)}')
            return
        for k in t:
            if k.startswith('<'):
                continue
            if k not in a:
                print(f'Missing key at {path}: {k}')
            else:
                compare_keys(t[k], a[k], f'{path}.{k}' if path else k)
        for k in a:
            if k not in t and not any(tk.startswith('<') for tk in t):
                print(f'Extra key at {path}: {k}')

compare_keys(tmpl, actual)
print('Key comparison complete.')
"
